const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.check}"/></svg>`;
function applyIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}applyIcons();
const $=id=>document.getElementById(id);const escapeHtml=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let selected=0,filter='all',quantity=1,resolved=false,confirmed=false,callback=false,running=false,paused=false,timer=null,currentMessage=0,currentChar=0,activeView='calls';
const calls=[{name:'한빛모터스',person:'김 실장',car:'아반떼 CN7',part:'프론트 범퍼',time:'14:42',duration:'03:24',status:'pending',phone:'4829',year:'2021년',plate:'128가 4829'},{name:'서초오토서비스',person:'박 대표',car:'쏘나타 DN8',part:'브레이크 패드',time:'14:15',duration:'02:18',status:'confirmed',phone:'1928',year:'2022년',plate:'245나 1928'},{name:'성진카센터',person:'이 실장',car:'그랜저 IG',part:'오일 필터',time:'13:58',duration:'01:42',status:'callback',phone:'7320',year:'2019년',plate:'36다 7320'},{name:'우리정비소',person:'최 대표',car:'투싼 NX4',part:'사이드 미러',time:'13:21',duration:'04:06',status:'confirmed',phone:'3081',year:'2023년',plate:'192라 3081'},{name:'서울모터스',person:'정 실장',car:'K5 DL3',part:'헤드램프',time:'11:46',duration:'02:56',status:'pending',phone:'8813',year:'2020년',plate:'156마 8813'}];
const script=[{who:'한빛모터스',time:'00:05',text:'여보세요, 한빛모터스 김 실장이에요. 아까 문의드렸던 아반떼 부품 좀 주문하려고요.'},{who:'나',time:'00:14',text:'네, 실장님. 아반떼 어떤 모델이실까요?'},{who:'한빛모터스',time:'00:21',text:'21년식 CN7이고요. 차번호가 128가 4829였나… 잠깐만요, 아마 맞을 거예요.'},{who:'나',time:'00:35',text:'네, 차량 번호는 한 번 더 확인 부탁드릴게요. 필요한 부품 말씀해 주세요.'},{who:'한빛모터스',time:'00:42',text:'앞범퍼 하나요. 도색 안 된 걸로요. 손님이 급하셔서 오늘 다섯 시 전까지 받을 수 있을까요?'},{who:'나',time:'01:02',text:'네, 재고랑 품번 확인해서 바로 연락드리겠습니다.'},{who:'한빛모터스',time:'01:09',text:'감사합니다. 차량 번호도 확인해서 문자로 보내드릴게요.'}];
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('toast').classList.remove('show'),3300)}
function statusLabel(s){return s==='confirmed'?'주문 확정':s==='callback'?'다시 전화':'확인 필요'}
function renderCalls(){const query=$('searchInput').value.toLowerCase();const visible=calls.map((c,i)=>({...c,index:i})).filter(c=>(filter==='all'||c.status!=='confirmed')&&`${c.name} ${c.car} ${c.part}`.toLowerCase().includes(query));$('callItems').innerHTML=visible.length?visible.map(c=>`<button class="call-item ${selected===c.index?'active':''}" data-call="${c.index}"><div class="call-item-top"><strong>${c.name}</strong><time>${c.time}</time></div><p>${c.car} · ${c.part}</p><div class="call-item-bottom"><span class="status-chip ${c.status}">${c.status==='confirmed'?'✓ ':''}${statusLabel(c.status)}</span><span>${c.duration}</span></div></button>`).join(''):'<div class="empty-message">검색 결과가 없어요.</div>';document.querySelectorAll('[data-call]').forEach(b=>b.onclick=()=>selectCall(Number(b.dataset.call)))}
function highlighted(text){return escapeHtml(text).replace('128가 4829','<mark class="warn">128가 4829</mark>').replace('21년식 CN7','<mark>21년식 CN7</mark>').replace('앞범퍼 하나','<mark>앞범퍼 하나</mark>').replace('오늘 다섯 시 전','<mark>오늘 다섯 시 전</mark>')}
function messageHtml(m,i,partial){return `<article class="message ${m.who==='나'?'agent':''}" id="message-${i}"><div class="speaker"><span class="speaker-dot"></span>${escapeHtml(m.who)}<time>${m.time}</time></div><p ${partial?'class="typing-cursor"':''}>${highlighted(m.text)}</p></article>`}
function renderTranscript(){const c=calls[selected];const content=selected===0?script:[{who:c.name,time:'00:05',text:`안녕하세요. ${c.name}입니다. ${c.car} ${c.part} 주문 부탁드립니다.`},{who:'나',time:'00:18',text:`네, ${c.year} ${c.car} 맞으시죠? 차량 번호 ${c.plate} 확인했습니다.`},{who:c.name,time:'00:32',text:`네, 맞아요. ${c.part} 하나 부탁드려요. 내일 오전까지 받을 수 있을까요?`},{who:'나',time:'00:44',text:'네, 재고 확인하고 출고 진행하겠습니다.'}];$('transcriptContent').innerHTML=content.map((m,i)=>messageHtml(m,i)).join('')+'<div class="transcript-end">— 통화 기록 끝 —</div>';renderInsight()}
function renderInsight(){const c=calls[selected];$('insightContent').innerHTML=`<div class="insight-section"><h3>✧ 통화 한눈에 보기</h3><p>${escapeHtml(c.name)}에서 ${escapeHtml(c.car)} ${escapeHtml(c.part)} 1개를 요청했습니다. ${selected===0?'도색 전 제품이며 오늘 17시 이전 배송을 희망합니다.':'내일 오전 배송을 희망합니다.'}</p></div><div class="insight-section"><h3>다음 할 일</h3><p>${selected===0?'① 차량 번호 128가 4829 재확인<br>② 프론트 범퍼 품번·재고 확인<br>③ 오늘 17시 이전 배송 가능 여부 안내':'① 부품 재고와 품번 확인<br>② 배송 일정 확인<br>③ 주문 확정 후 출고'}</p></div><div class="insight-section"><h3>담당자 판단이 필요한 정보</h3><p>차대번호에 맞는 정확한 품번과 재고는 담당자가 확인합니다. AI는 주문 초안만 작성합니다.</p></div>`}
function selectCall(index){stopDemo(false);selected=index;const c=calls[index];confirmed=c.status==='confirmed';resolved=confirmed||index!==0;quantity=1;callback=c.status==='callback';$('customerName').textContent=c.name;$('customerAvatar').textContent=c.name[0];$('customerMeta').textContent=`${c.person} · 010-••••-${c.phone}`;$('durationLabel').textContent=c.duration;$('shopField').value=c.name;$('personField').value=c.person;$('carField').value=c.car;$('yearField').value=c.year;$('plateField').value=c.plate;$('partField').value=confirmed?'86511-'+(index===1?'L1000':'N9000'):'';$('urgencyField').selectedIndex=index===0?0:2;$('memoField').value=index===0?'도색 전 제품 요청. 오늘 5시 이전 배송 희망.':'내일 오전 배송 희망.';$('quantityValue').textContent=quantity;document.querySelector('.part-top strong').textContent=c.part;document.querySelector('.part-top small').textContent=index===0?'“앞범퍼 하나” · 00:42':`“${c.part} 하나” · 00:32`;updateOrderState();renderTranscript();renderCalls()}
function updateOrderState(){$('uncertaintyBox').classList.toggle('hidden',resolved);$('uncertainLabel').classList.toggle('hidden',resolved);$('plateField').classList.toggle('uncertain',!resolved);$('draftBadge').textContent=confirmed?'확정됨':'초안';$('callStatus').textContent=confirmed?'주문 확정':running?'실시간 기록 중':statusLabel(calls[selected].status);$('confirmBtn').innerHTML=icon('check')+(confirmed?'확정된 주문 보기':'주문 확인하고 확정');$('confirmHint').textContent=confirmed?'주문 보드에서 출고 상태를 관리할 수 있어요.':'차량 번호와 품번을 확인한 뒤 확정해 주세요.';$('callbackBtn').innerHTML=icon('phone')+(callback?'다시 전화할 목록에서 제거':'다시 전화할 목록에 추가');$('confirmedMetric').innerHTML=(8+(calls[0].status==='confirmed'?1:0))+' <em>건</em>';$('pendingMetric').innerHTML=(3-(calls[0].status==='confirmed'?1:0))+' <em>건</em>';$('orderCount').textContent=8+(calls[0].status==='confirmed'?1:0)}
function switchView(view){activeView=view;document.querySelectorAll('.view').forEach(el=>el.classList.add('hidden'));$(view+'View').classList.remove('hidden');document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('pageName').textContent=view==='calls'?'통화 기록':view==='orders'?'주문 보드':'오늘의 브리핑';$('heading').textContent=view==='calls'?'통화에 집중하세요. 정리는 콜노트가 할게요.':view==='orders'?'주문부터 출고까지, 한눈에.':'오늘의 업무를 가볍게 마무리하세요.';$('subheading').textContent=view==='calls'?'놓친 주문 없이, 한 번의 확인으로 출고까지.':view==='orders'?'통화에서 시작된 주문의 다음 단계를 관리하세요.':'놓치면 안 되는 주문과 다시 전화할 곳을 모았어요.';if(view==='orders')renderBoard();if(view==='summary')renderSummary()}
function renderBoard(){const columns=[['pending','확인 필요'],['confirmed','출고 준비'],['shipped','출고 완료']];$('ordersView').innerHTML='<div class="board-grid">'+columns.map(([status,title])=>`<section class="board-column"><h2>${title} <span style="opacity:.45;margin-left:8px">${calls.filter(c=>(status==='pending'?c.status==='pending'||c.status==='callback':c.status===status)).length}</span></h2>${calls.map((c,i)=>({...c,index:i})).filter(c=>status==='pending'?c.status==='pending'||c.status==='callback':c.status===status).map(c=>`<article class="board-card"><span class="status-chip ${c.status}">${statusLabel(c.status==='shipped'?'confirmed':c.status)}</span><h3 style="margin-top:12px">${c.name}</h3><p>${c.car} · ${c.part}<br>수량 ${c.quantity||1}개 · ${c.year}</p><small>오늘 ${c.time} 통화에서 생성</small><button class="secondary" data-board-call="${c.index}" ${status==='confirmed'?'data-ship="true"':''}>${status==='confirmed'?'출고 완료로 변경':status==='shipped'?'통화 원문 보기':'주문 확인하기'}</button></article>`).join('')||'<div class="empty-message">아직 주문이 없어요.</div>'}</section>`).join('')+'</div>';document.querySelectorAll('[data-board-call]').forEach(b=>b.onclick=()=>{if(b.dataset.ship){calls[Number(b.dataset.boardCall)].status='shipped';renderBoard();toast('출고 완료로 변경했어요.')}else{selectCall(Number(b.dataset.boardCall));switchView('calls')}})}
function renderSummary(){$('summaryView').innerHTML=`<div class="summary-grid"><section class="summary-card"><div class="eyebrow">DAILY BRIEFING · 11.11</div><h2>오늘도 12번의 연결이 있었어요.</h2><p>총 38분 24초의 통화에서 ${8+(calls[0].status==='confirmed'?1:0)}건의 주문을 확정했어요.<br>확인이 필요한 주문부터 살펴보면, 놓친 일 없이 마무리할 수 있어요.</p><div class="insight-section" style="margin-top:25px"><h3>먼저 챙겨 주세요</h3><p>한빛모터스의 프론트 범퍼는 오늘 17시 이전 배송 요청이에요.<br>차량 번호와 재고를 확인한 뒤 배송 가능 여부를 알려 주세요.</p></div><div class="insight-section"><h3>가장 많이 주문한 부품</h3><p>브레이크 패드 4건 · 오일 필터 3건 · 범퍼 2건</p></div><button class="secondary" id="copySummary">${icon('copy')}브리핑 복사</button></section><section class="summary-card"><h2>다시 연락할 곳</h2><p>확인할 내용을 함께 남겨뒀어요.</p>${calls.map((c,i)=>({...c,index:i})).filter(c=>c.status==='callback'||c.status==='pending').map(c=>`<div class="summary-call"><div><strong>${c.name}</strong><small>${c.index===0?'차량 번호 · 긴급 배송 확인':'품번과 입고 일정 확인'}</small></div><button data-summary-call="${c.index}">통화 보기</button></div>`).join('')}</section></div>`;document.querySelectorAll('[data-summary-call]').forEach(b=>b.onclick=()=>{selectCall(Number(b.dataset.summaryCall));switchView('calls')});$('copySummary').onclick=()=>copyText(`오늘 통화 12건 · 주문 확정 ${8+(calls[0].status==='confirmed'?1:0)}건\n확인 필요: 한빛모터스 차량 번호·긴급 배송, 성진카센터 입고 일정.`)}
function pulse(id,value){$(id).value=value;$(id).classList.remove('extracting');void $(id).offsetWidth;$(id).classList.add('extracting')}
function startDemo(){switchView('calls');selectCall(0);confirmed=false;resolved=false;running=true;paused=false;currentMessage=0;currentChar=0;calls[0].status='pending';$('transcriptContent').innerHTML='';['shopField','personField','carField','yearField','plateField','partField','memoField'].forEach(id=>$(id).value='');$('saveLabel').innerHTML='<span class="dot"></span>대화를 기록하는 중';$('liveTitle').textContent='실시간으로 대화를 기록하고 있어요';$('liveSub').textContent='샘플 시뮬레이션 · 실제 마이크는 사용하지 않아요';$('wave').classList.add('running');$('pauseBtn').classList.remove('hidden');$('recordBtn').innerHTML=icon('stop')+'기록 종료';document.querySelector('[data-tab="transcript"]').click();updateOrderState();renderCalls();timer=setInterval(streamTick,42)}
function streamTick(){if(paused||!running)return;if(currentMessage>=script.length){stopDemo(true);return}const m=script[currentMessage];let article=$('message-'+currentMessage);if(!article){$('transcriptContent').insertAdjacentHTML('beforeend',messageHtml({...m,text:''},currentMessage,true));article=$('message-'+currentMessage)}currentChar+=2;article.querySelector('p').innerHTML=highlighted(m.text.slice(0,currentChar));$('transcriptContent').scrollTop=$('transcriptContent').scrollHeight;if(currentChar>=m.text.length){article.querySelector('p').classList.remove('typing-cursor');if(currentMessage===0){pulse('shopField','한빛모터스');pulse('personField','김 실장')}if(currentMessage===2){pulse('carField','아반떼 CN7');pulse('yearField','2021년');pulse('plateField','128가 4829')}if(currentMessage===4){pulse('memoField','도색 전 제품 요청. 오늘 5시 이전 배송 희망.');document.querySelector('.part-card').classList.add('extracting')}currentMessage++;currentChar=0}}
function stopDemo(completed){clearInterval(timer);timer=null;running=false;paused=false;$('wave').classList.remove('running');$('pauseBtn').classList.add('hidden');$('pauseBtn').innerHTML=icon('pause');$('recordBtn').innerHTML=icon('play')+'다시 재생';$('liveTitle').textContent=completed?'주문 초안을 정리했어요':'대화의 맥락까지, 놓치지 않게';$('liveSub').textContent='예시 데이터로 실시간 기록을 경험해 보세요';$('saveLabel').innerHTML='<span class="dot"></span>자동 저장됨';if(completed){$('transcriptContent').insertAdjacentHTML('beforeend','<div class="transcript-end">— 샘플 통화 종료 · 주문 카드 완성 —</div>');toast('통화 기록을 마쳤어요. 오른쪽 주문 카드를 확인해 주세요.')}if(calls[selected])$('callStatus').textContent=statusLabel(calls[selected].status)}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('클립보드에 복사했어요.')}catch(e){toast('이 브라우저에서는 복사를 사용할 수 없어요. 대화 내용을 직접 선택해 주세요.')}}
$('wave').innerHTML='<i></i>'.repeat(9);$('recordBtn').onclick=()=>running?stopDemo(true):startDemo();$('startSide').onclick=startDemo;$('pauseBtn').onclick=()=>{paused=!paused;$('pauseBtn').innerHTML=icon(paused?'play':'pause');$('pauseBtn').setAttribute('aria-label',paused?'기록 계속':'일시 정지');$('wave').classList.toggle('running',!paused);$('liveTitle').textContent=paused?'기록을 잠시 멈췄어요':'실시간으로 대화를 기록하고 있어요'};$('resolveBtn').onclick=()=>{if(!$('plateField').value.trim()){toast('차량 번호를 입력해 주세요.');$('plateField').focus();return}resolved=true;updateOrderState();toast('차량 번호 확인을 완료했어요.')};$('plateField').oninput=()=>{resolved=false;updateOrderState()};$('plusBtn').onclick=()=>$('quantityValue').textContent=++quantity;$('minusBtn').onclick=()=>$('quantityValue').textContent=quantity=Math.max(1,quantity-1);$('confirmBtn').onclick=()=>{if(confirmed){switchView('orders');return}if(running){toast('통화 기록을 종료한 뒤 주문을 확인해 주세요.');return}if(!resolved){toast('불확실한 차량 번호를 먼저 확인해 주세요.');$('plateField').focus();return}if(!$('partField').value.trim()){toast('정확한 품번을 입력해 주세요. 예: 86511-AA000');$('partField').focus();return}if(!$('shopField').value.trim()||!$('carField').value.trim()){toast('거래처와 차종을 입력해 주세요.');return}confirmed=true;calls[selected].quantity=quantity;calls[selected].status='confirmed';calls[selected].name=$('shopField').value;calls[selected].car=$('carField').value;updateOrderState();renderCalls();toast('주문을 확정했어요. 주문 보드의 출고 준비에 추가되었습니다.')};$('callbackBtn').onclick=()=>{callback=!callback;calls[selected].status=callback?'callback':confirmed?'confirmed':'pending';updateOrderState();renderCalls();toast(callback?'다시 전화할 목록에 추가했어요.':'다시 전화할 목록에서 제거했어요.')};document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>switchView(b.dataset.view));document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('.filter').forEach(e=>e.classList.toggle('active',e===b));renderCalls()});$('searchInput').oninput=renderCalls;document.querySelectorAll('.transcript-tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.transcript-tab').forEach(e=>e.classList.toggle('active',e===b));$('transcriptContent').classList.toggle('hidden',b.dataset.tab!=='transcript');$('insightContent').classList.toggle('hidden',b.dataset.tab!=='insight')});$('copyBtn').onclick=()=>copyText($('transcriptContent').innerText);$('uploadBtn').onclick=()=>$('fileInput').click();$('fileInput').onchange=()=>{const file=$('fileInput').files[0];if(file){toast(`${file.name} 선택됨 · 실제 분석 대신 샘플 통화 데모를 재생합니다.`);startDemo();$('liveSub').textContent='파일은 업로드되지 않아요 · 샘플 시뮬레이션';$('fileInput').value=''}};$('workspaceBtn').onclick=()=>toast('대한오토 부품 · T07 데모 워크스페이스입니다.');$('helpBtn').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();$('helpStart').onclick=()=>{$('helpDialog').close();startDemo()};$('helpDialog').onclick=e=>{if(e.target===$('helpDialog'))$('helpDialog').close()};selectCall(0);
